import random
import numpy as np
import base64
import bz2
import pickle
from treys import Card, Evaluator
from pkbot.engine import ActionFold, ActionCall, ActionCheck, ActionRaise, ActionBid

evaluator = Evaluator()

SUITS = ['s', 'h', 'd', 'c']
RANKS = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A']
FULL_DECK = [r+s for r in RANKS for s in SUITS]
RANK_VALUES = {r: i for i, r in enumerate(RANKS, 2)}

BRAIN_PAYLOAD = ''

class FoldedCFRBrain:
    def __init__(self, payload):
        byte_data = base64.b64decode(payload)
        decompressed_data = bz2.decompress(byte_data)
        self.weights = pickle.loads(decompressed_data)

    def relu(self, x): return np.maximum(0, x)

    def predict(self, state_vector):
        x = np.array(state_vector, dtype=np.float16)
        x = self.relu(np.dot(x, self.weights[0]) + self.weights[1])
        x = self.relu(np.dot(x, self.weights[2]) + self.weights[3])
        x = self.relu(np.dot(x, self.weights[4]) + self.weights[5])
        return np.dot(x, self.weights[6]) + self.weights[7]

PREFLOP_EQUITY = {
    "AA": 0.852, "KK": 0.824, "QQ": 0.799, "JJ": 0.775, "TT": 0.751, "99": 0.716, "88": 0.687, "77": 0.662, "66": 0.632, "55": 0.603, "44": 0.570, "33": 0.536, "22": 0.503,
    "AKs": 0.670, "AQs": 0.661, "AJs": 0.654, "ATs": 0.647, "A9s": 0.630, "A8s": 0.621, "A7s": 0.610, "A6s": 0.599, "A5s": 0.599, "A4s": 0.589, "A3s": 0.580, "A2s": 0.570, 
    "KQs": 0.633, "KJs": 0.625, "KTs": 0.618, "K9s": 0.600, "K8s": 0.582, "K7s": 0.573, "K6s": 0.563, "K5s": 0.553, "K4s": 0.542, "K3s": 0.531, "K2s": 0.520, "QJs": 0.603, 
    "AKo": 0.653, "AQo": 0.644, "AJo": 0.636, "ATo": 0.628, "A9o": 0.610, "A8o": 0.599, "A7o": 0.587, "A6o": 0.575, "A5o": 0.574, "A4o": 0.563, "A3o": 0.553, "A2o": 0.542, 
    "72o": 0.312
}

class Player:
    def __init__(self):
        try:
            self.brain = FoldedCFRBrain(BRAIN_PAYLOAD)
            self.brain_active = True
        except Exception:
            self.brain_active = False 
            
        # --- ADVANCED HUD TRACKING ---
        self.hands_played = 0
        self.opp_vpip_count = 0        # Voluntarily Put In Pot
        self.opp_pfr_count = 0         # Preflop Raises
        self.opp_aggressions = 0       # Total raises/bets
        self.opp_calls = 0             # Total passive calls
        self.flops_seen = 0
        self.showdowns_seen = 0

    def get_opp_profile(self):
        """Safely calculates HUD metrics. Returns 'unknown' if variance is too high."""
        # Require 25 hands of data before assuming ANY traits to prevent erratic exploitation
        if self.hands_played < 25:
            return 'unknown'
            
        vpip = self.opp_vpip_count / self.hands_played
        pfr = self.opp_pfr_count / self.hands_played
        af = self.opp_aggressions / max(1, self.opp_calls) # Aggression Factor
        wtsd = self.showdowns_seen / max(1, self.flops_seen) # Went to Showdown
        
        # Profile: The Calling Station (Plays too many hands, passive, refuses to fold)
        if vpip > 0.55 and af < 1.0 and wtsd > 0.35: return 'station'
        
        # Profile: The Nit (Plays very few hands, highly risk-averse)
        if vpip < 0.20 and pfr < 0.10: return 'nit'
        
        # Profile: The Maniac (Hyper-aggressive, bluffs relentlessly)
        if vpip > 0.60 and af > 2.5: return 'maniac'
        
        return 'balanced' # Trust the GTO brain

    def evaluate_hand_strength(self, current_state):
        if current_state.street == 'preflop':
            key = self.get_hand_key(current_state.my_hand)
            return PREFLOP_EQUITY.get(key, 0.40)
            
        t_board = [Card.new(c) for c in current_state.board]
        t_hole = [Card.new(c) for c in current_state.my_hand]
        
        if hasattr(current_state, 'sneak_peek_card') and current_state.sneak_peek_card and getattr(current_state, 'auction_won', False):
            t_hole.append(Card.new(current_state.sneak_peek_card))
                
        try:
            return 1.0 - (evaluator.evaluate(t_hole, t_board) / 7462.0)
        except: 
            return 0.5 


    def on_hand_end(self, game_info, current_state):
        """Silently tracks the 4 major metrics at the end of the hand."""
        self.hands_played += 1
        my_wager = getattr(current_state, 'my_wager', 0)
        opp_wager = getattr(current_state, 'opp_wager', 0)
        
        # 1. VPIP (Did they voluntarily put chips in preflop?)
        if opp_wager > 10: 
            self.opp_vpip_count += 1
            
        # 2. PFR (Did they raise preflop?)
        if current_state.street == 'preflop' and opp_wager > my_wager and opp_wager > 20: 
            self.opp_pfr_count += 1
            
        # 3. Aggression vs Passive (Approximation for AF)
        if opp_wager > my_wager:
            self.opp_aggressions += 1
        elif opp_wager == my_wager and opp_wager > 10:
            self.opp_calls += 1
            
        # 4. Showdown Tracking (WTSD)
        if len(current_state.board) >= 3:
            self.flops_seen += 1
            # If the game reached terminal and nobody folded
            if getattr(current_state, 'folded', -1) == -1:
                self.showdowns_seen += 1

    # ==========================================
    # ENGINE MAPPERS
    # ==========================================
    def vectorize_state(self, current_state):
        hand_strength = self.evaluate_hand_strength(current_state)
        pot = max(1, current_state.pot)
        call_amount = getattr(current_state, 'cost_to_call', 0)
        my_stack = getattr(current_state, 'my_stack', 10000)
        
        pot_odds = call_amount / (pot + call_amount) if (pot + call_amount) > 0 else 0.0
        spr = my_stack / pot
        street_val = {'preflop': 0.0, 'auction': 0.5, 'flop': 1.0, 'turn': 2.0, 'river': 3.0}.get(current_state.street, 0.0)
        position_val = 1.0 if getattr(current_state, 'button', False) else 0.0
        opp_bet_ratio = call_amount / pot
        
        return np.array([hand_strength, pot_odds, spr, street_val, position_val, opp_bet_ratio], dtype=np.float16)

    def apply_mit_threshold(self, strategy, threshold=0.10):
        """
        Implementation of the MIT CFR Thresholding rule[cite: 149].
        Zeros out marginal plays (<= 10%) to eliminate statistical noise.
        """
        # Set small probabilities to 0.0
        strategy[strategy <= threshold] = 0.0
        
        # Re-normalize the strategy so it sums to 1.0
        sum_prob = np.sum(strategy)
        if sum_prob > 0:
            return strategy / sum_prob
        
        # Fallback: If everything was pruned, return a safe Fold/Check (index 0)
        return np.array([1.0, 0.0, 0.0, 0.0])
    
    def map_index_to_action(self, action_idx, current_state):
        my_stack = getattr(current_state, 'my_stack', 10000)
        pot = current_state.pot

        # Delta EV Auction Engine with "Never 0" Rule
        if current_state.street == 'auction':
            eq2 = self.evaluate_hand_strength(current_state)
            eq3_estimate = min(0.95, eq2 + 0.15) 
            delta_ev = (eq3_estimate - eq2) * pot
            
            # Prevent 1-chip steals observed in logs
            min_bid = max(10, int(pot * 0.05))
            final_bid = int(max(min_bid, delta_ev))
            
            if current_state.can_act(ActionBid):
                return ActionBid(min(final_bid, my_stack))
            return ActionCheck()

        # ==========================================
        # 2. STANDARD BETTING STREETS
        # ==========================================
        # Index 0: Fold/Check
        if action_idx == 0:
            return ActionCheck() if current_state.can_act(ActionCheck) else ActionFold()

        # CFR Abstraction Mapping: 1=26% Pot, 2=105% Pot, 3=All-In
        bids = [0, int(pot * 0.26), int(pot * 1.05), my_stack]
        target_investment = bids[action_idx]
        cost_to_call = current_state.cost_to_call

        if target_investment <= cost_to_call:
            if current_state.can_act(ActionCall): return ActionCall()
            return ActionCheck() if current_state.can_act(ActionCheck) else ActionFold()
        else:
            if current_state.can_act(ActionRaise):
                min_r, max_r = current_state.raise_bounds
                # Ensure we respect engine-enforced raise boundaries
                return ActionRaise(max(min_r, min(target_investment, max_r)))
            if current_state.can_act(ActionCall): return ActionCall()
            return ActionFold()

    def get_move(self, game_info, current_state):
        if game_info.time_bank < 1.0 or not self.brain_active:
            return self.panic_move(current_state)

        # 1. Ask the GTO Brain for raw regrets
        state_vector = self.vectorize_state(current_state)
        regrets = self.brain.predict(state_vector)
        
        # 2. Convert to probabilities (Regret Matching)
        pos_regrets = np.maximum(regrets, 0)
        sum_pos = np.sum(pos_regrets)
        raw_strategy = pos_regrets / sum_pos if sum_pos > 0 else np.ones(4) / 4.0
        
        # 3. Apply the MIT 10% Thresholding Rule [cite: 149]
        # This makes our strategy more robust against high-variance "lucky" bots.
        refined_strategy = self.apply_mit_threshold(raw_strategy, 0.10)
        
        # 4. Probabilistic Sampling (Game Theory mixed strategy)
        chosen_action_idx = np.random.choice([0, 1, 2, 3], p=refined_strategy)
        
        # 5. Exploitative Supervision (Trench-Breaker)
        hand_strength = self.evaluate_hand_strength(current_state)
        if hand_strength > 0.85 and chosen_action_idx == 0:
            # Never check a monster against low-ranked bots
            chosen_action_idx = 1 if current_state.cost_to_call == 0 else 2

        return self.map_index_to_action(chosen_action_idx, current_state)

    def get_hand_key(self, cards):
        if len(cards) < 2: return "72o"
        r1, s1, r2, s2 = cards[0][0], cards[0][1], cards[1][0], cards[1][1]
        if RANK_VALUES.get(r1, 0) < RANK_VALUES.get(r2, 0): r1, r2 = r2, r1
        if r1 == r2: return f"{r1}{r2}"
        return f"{r1}{r2}s" if s1 == s2 else f"{r1}{r2}o"

    def panic_move(self, current_state):
        return ActionCheck() if current_state.can_act(ActionCheck) else ActionFold()